(6674856, 998569, 49018, '<td valign="top">Darn brilliant. Either staged or the priest is quite a nice guy (or he threw an aspersory at you an instant later, I know a few that would)<br/>9</td>', 'Darn brilliant. Either staged or the priest is quite a nice guy (or he threw an aspersory at you an instant later, I know a few that would)9', '2012-02-13 18:54:24.000000', NULL, 1),
(6674859, 998394, 49018, '<td valign="top">I find the circular window quite interesting. Disguised camera?</td>', 'I find the circular window quite interesting. Disguised camera?', '2012-02-13 18:55:49.000000', NULL, 1),
(6674861, 998636, 49018, '<td valign="top">That''s pretty cute, colourful and very effectively lit. I love that it''s all amde of paper sheets. Is it resting over a glass table or a large softbox?</td>', 'That''s pretty cute, colourful and very effectively lit. I love that it''s all amde of paper sheets. Is it resting over a glass table or a large softbox?', '2012-02-13 18:57:41.000000', NULL, 1),
(6674863, 998638, 49018, '<td valign="top">Yeah, it helps for that too, I can sympathize..</td>', 'Yeah, it helps for that too, I can sympathize..', '2012-02-13 18:58:36.000000', NULL, 1),
(6674871, 998655, 49018, '<td valign="top">Was this taken from a plane?<br/>I see the similitude with the three top ones, a bit less with the two central legato ones, but hey, perhaps aking them to pose it in a slightly different way was not quite possible :D</td>', 'Was this taken from a plane?I see the similitude with the three top ones, a bit less with the two central legato ones, but hey, perhaps aking them to pose it in a slightly different way was not quite possible :D', '2012-02-13 19:06:54.000000', NULL, 1),
(6674885, 998354, 49018, '<td valign="top">The fact that the fingers seem to fly overt he keys without really pressing them, along with the title, makes me think of irascible neighbours :D<br/>Sorry, I tend and read things though my experience :)</td>', 'The fact that the fingers seem to fly overt he keys without really pressing them, along with the title, makes me think of irascible neighbours :DSorry, I tend and read things though my experience :)', '2012-02-13 19:14:38.000000', NULL, 1),
(6674888, 997702, 49018, '<td valign="top">Jeez, that''s  a bit scary.<br/>Tiny doggy, cute.</td>', 'Jeez, that''s  a bit scary.Tiny doggy, cute.', '2012-02-13 19:15:49.000000', NULL, 1),
(6674892, 998577, 49018, '<td valign="top">Fascinating. It''s not often that one sees the intricacies of a woodwind. Not quite as simple as you would imagine.</td>', 'Fascinating. It''s not often that one sees the intricacies of a woodwind. Not quite as simple as you would imagine.', '2012-02-13 19:16:46.000000', NULL, 1),
(6674896, 997593, 49018, '<td valign="top">Interesting instrument.</td>', 'Interesting instrument.', '2012-02-13 19:18:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6674898, 998574, 49018, '<td valign="top">I like the postprocessing.</td>', 'I like the postprocessing.', '2012-02-13 19:19:13.000000', NULL, 1),
(6674899, 998451, 49018, '<td valign="top">Cute, all wood.</td>', 'Cute, all wood.', '2012-02-13 19:19:33.000000', NULL, 1),
(6674914, 997318, 49018, '<td valign="top">I am honestly uncertain about this. It makes me think that, dependently on which tones are augmented and diminished, you might have a change in signature and tonality, without actually changing pitch, so stability.<br/>But quite uncertain really.</td>', 'I am honestly uncertain about this. It makes me think that, dependently on which tones are augmented and diminished, you might have a change in signature and tonality, without actually changing pitch, so stability.But quite uncertain really.', '2012-02-13 19:23:57.000000', NULL, 1),
(6674917, 998647, 49018, '<td valign="top">I like this, well delayed.</td>', 'I like this, well delayed.', '2012-02-13 19:25:07.000000', NULL, 1),
(6674926, 998385, 49018, '<td valign="top">A thin whistle, that travels quite far for sure.</td>', 'A thin whistle, that travels quite far for sure.', '2012-02-13 19:28:44.000000', NULL, 1),
(6674936, 998604, 49018, '<td valign="top">Celtic guitar? A vague resemblance with Steve Baughman, but might be wishful hoping on my part :) Does he play clawhammer style?</td>', 'Celtic guitar? A vague resemblance with Steve Baughman, but might be wishful hoping on my part :) Does he play clawhammer style?', '2012-02-13 19:32:46.000000', NULL, 1),
(6674939, 998622, 49018, '<td valign="top">I like it. It''s  matter of taste but perhaps a lighter or darked background would have given more presence.</td>', 'I like it. It''s  matter of taste but perhaps a lighter or darked background would have given more presence.', '2012-02-13 19:35:02.000000', NULL, 1),
(6674942, 998646, 49018, '<td valign="top">I am trying really hard to make what the silvery thing on the walk board is. I feel it might be part of the story, but I can''t really figure out what it is or might represent..</td>', 'I am trying really hard to make what the silvery thing on the walk board is. I feel it might be part of the story, but I can''t really figure out what it is or might represent..', '2012-02-13 19:37:39.000000', NULL, 1),
(6674948, 998368, 49018, '<td valign="top">A very disorientating geometry. Focal compression and high presence work well here, no relief for the eye.. If I see a tie with the title is in the oppressing feeling that an ostinato *can* convey. Interesting.</td>', 'A very disorientating geometry. Focal compression and high presence work well here, no relief for the eye.. If I see a tie with the title is in the oppressing feeling that an ostinato *can* convey. Interesting.', '2012-02-13 19:42:11.000000', NULL, 1),
(6674950, 998573, 49018, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2012-02-13 19:43:06.000000', NULL, 1),
(6674957, 998346, 49018, '<td valign="top">Interesting, I didn''t know this Dudamel guy, and still can''t judge how well this might portrait his conducting style. Still, an excellent capture, composition and PP.</td>', 'Interesting, I didn''t know this Dudamel guy, and still can''t judge how well this might portrait his conducting style. Still, an excellent capture, composition and PP.', '2012-02-13 19:45:56.000000', NULL, 1),
(6674960, 998609, 49018, '<td valign="top">Interesting idea and processing. The repetition of the same idea in several overlapping variations.</td>', 'Interesting idea and processing. The repetition of the same idea in several overlapping variations.', '2012-02-13 19:48:16.000000', NULL, 1),
(6674968, 998650, 100831, '<td valign="top">beautiful colors... I''m hearing something like Debussy Children''s Corner ... lyrical but with a purpose.</td>', 'beautiful colors... I''m hearing something like Debussy Children''s Corner ... lyrical but with a purpose.', '2012-02-13 19:52:48.000000', NULL, 1),
(6674969, 998645, 49018, '<td valign="top">The thin line between meaningful repetition and annoying cacophony?<br/>Or between endless repetitions of a riff without never quite sounding the same. Django was really good at that, the same note 5 measures non stop, not one sounding the same for dynamic or timbre.</td>', 'The thin line between meaningful repetition and annoying cacophony?Or between endless repetitions of a riff without never quite sounding the same. Django was really good at that, the same note 5 measures non stop, not one sounding the same for dynamic or timbre.', '2012-02-13 19:53:01.000000', NULL, 1),
(6674970, 998604, 100831, '<td valign="top">love the concentration</td>', 'love the concentration', '2012-02-13 19:53:23.000000', NULL, 1),
(6674971, 998549, 100831, '<td valign="top">yes, it would. great thought and image.</td>', 'yes, it would. great thought and image.', '2012-02-13 19:54:12.000000', NULL, 1),
(6675026, 998650, 67152, '<td valign="top">I am thinking a G7 chord...i like that chord</td>', 'I am thinking a G7 chord...i like that chord', '2012-02-13 20:23:33.000000', NULL, 1),
(6675103, 998346, 94815, '<td valign="top">Stirring up the cosmos.</td>', 'Stirring up the cosmos.', '2012-02-13 21:05:50.000000', NULL, 1),
(6675282, 998557, 77196, '<td valign="top">Ah, my favorite composer - PDQ Bach! <br/>The entire shot is fill the frame, except for that triangular "hole" in the upper left...</td>', 'Ah, my favorite composer - PDQ Bach! The entire shot is fill the frame, except for that triangular "hole" in the upper left...', '2012-02-13 22:23:28.000000', NULL, 1),
