(6675290, 998607, 77196, '<td valign="top">Great concept, but to me it looks just too dark - perhaps just the monitor...</td>', 'Great concept, but to me it looks just too dark - perhaps just the monitor...', '2012-02-13 22:24:41.000000', NULL, 1),
(6675298, 998604, 77196, '<td valign="top">To me, his expression doesn''t do him justice - he looks disgusted, bored, unhappy - all at the same time.</td>', 'To me, his expression doesn''t do him justice - he looks disgusted, bored, unhappy - all at the same time.', '2012-02-13 22:27:42.000000', NULL, 1),
(6675312, 998569, 77196, '<td valign="top">The music director is too easy to miss, and is crucial to tying the shot to "music". The picture is quite "busy" with lots of focal points. The points do tie nicely together in tone and interest.</td>', 'The music director is too easy to miss, and is crucial to tying the shot to "music". The picture is quite "busy" with lots of focal points. The points do tie nicely together in tone and interest.', '2012-02-13 22:33:19.000000', NULL, 1),
